import { test, expect } from '@playwright/test';

test.describe('Payment Card Declined Error State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display clear error message when payment card is declined', async ({ page }) => {
    // Setup API interception for declined card
    await page.route('**/api/payment/process', (route) => {
      route.abort('failed');
    });

    // Fill in valid card details
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('411111111111111');

    const expiryInput = page.getByLabel('Expiry Date');
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /submit payment/i });
    await submitButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/payment declined/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message contains specific details
    await expect(errorMessage).toContainText('Your card was declined');

    // Verify error state is visible
    const errorContainer = page.locator('[data-testid="error-container"]');
    await expect(errorContainer).toBeVisible();

    // Verify form is still visible for retry
    const form = page.locator('[data-testid="payment-form"]');
    await expect(form).toBeVisible();
  });

  test('should allow user to retry payment after decline error', async ({ page }) => {
    // Setup API interception for declined card
    await page.route('**/api/payment/process', (route) => {
      route.abort('failed');
    });

    // Fill in card details
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('411111111111111');

    const expiryInput = page.getByLabel('Expiry Date');
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Click submit button to trigger decline
    const submitButton = page.getByRole('button', { name: /submit payment/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/payment declined/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Click retry button
    await retryButton.click();

    // Verify form is cleared and ready for new input
    await expect(cardNumberInput).toHaveValue('');
    await expect(expiryInput).toHaveValue('');
    await expect(cvvInput).toHaveValue('');

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();
  });
});
